create table if not exists public.profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 24),color text not null default '#ff7a2d',is_kids boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.continue_watching(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,profile_id uuid not null references public.profiles(id) on delete cascade,mal_id integer not null,episode integer not null,audio text not null default 'sub' check(audio in ('sub','dub')),position_seconds integer not null default 0,duration_seconds integer not null default 0,updated_at timestamptz not null default now(),unique(profile_id,mal_id,episode,audio));
alter table public.profiles enable row level security;alter table public.continue_watching enable row level security;
drop policy if exists profiles_select_own on public.profiles;create policy profiles_select_own on public.profiles for select to authenticated using((select auth.uid())=user_id);
drop policy if exists profiles_insert_own on public.profiles;create policy profiles_insert_own on public.profiles for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists profiles_update_own on public.profiles;create policy profiles_update_own on public.profiles for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists profiles_delete_own on public.profiles;create policy profiles_delete_own on public.profiles for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists cw_select_own on public.continue_watching;create policy cw_select_own on public.continue_watching for select to authenticated using((select auth.uid())=user_id);
drop policy if exists cw_insert_own on public.continue_watching;create policy cw_insert_own on public.continue_watching for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists cw_update_own on public.continue_watching;create policy cw_update_own on public.continue_watching for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists cw_delete_own on public.continue_watching;create policy cw_delete_own on public.continue_watching for delete to authenticated using((select auth.uid())=user_id);
create index if not exists profiles_user_idx on public.profiles(user_id);create index if not exists cw_profile_updated_idx on public.continue_watching(profile_id,updated_at desc);